-- Protected AA Toolkit distribution build.
local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local function decode(value)
    value=value:gsub('[^'..alphabet..'=]','')
    return (value:gsub('.',function(char)
        if char=='='then return ''end
        local index=alphabet:find(char,1,true)-1
        local bits=''
        for shift=5,0,-1 do bits=bits..(math.floor(index/2^shift)%2==1 and '1'or'0')end
        return bits
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(bits)
        if #bits~=8 then return ''end
        local byte=0
        for index=1,8 do if bits:sub(index,index)=='1'then byte=byte+2^(8-index)end end
        return string.char(byte)
    end))
end
